<?php
namespace App\Services\Upgrade;
use App\Models\IkontrolInstance; use Illuminate\Database\ConnectionInterface;
final class InstanceFiscalCapabilityAuditor {
 public function audit(IkontrolInstance$instance,IkontrolVersionDefinition$definition,ConnectionInterface$db):array{$root=rtrim((string)$instance->absolute_path,'/\\');$requiredTables=$definition->manifest['fiscal_capabilities']['tables']??[];$requiredFiles=$definition->manifest['fiscal_capabilities']['files']??[];$tables=collect($db->select('SELECT TABLE_NAME FROM INFORMATION_SCHEMA.TABLES WHERE TABLE_SCHEMA = ?',[$instance->db_name]))->pluck('TABLE_NAME')->map(fn($v)=>(string)$v)->all();$presentTables=array_values(array_intersect($requiredTables,$tables));$presentFiles=[];foreach($requiredFiles as$f)if(is_file($root.DIRECTORY_SEPARATOR.str_replace('/',DIRECTORY_SEPARATOR,$f)))$presentFiles[]=$f;$total=count($requiredTables)+count($requiredFiles);$present=count($presentTables)+count($presentFiles);$state=$present===0?'NOT_INSTALLED':($present===$total?'INSTALLED':($present<$total?'PARTIAL':'INCONSISTENT'));$severity=$state==='INCONSISTENT'?'CRITICAL':($state==='PARTIAL'?'WARNING':'INFO');return[UpgradeAuditItem::make('FISCAL','CAPABILITY','fiscal',$state,$severity,['tables'=>$presentTables,'files'=>$presentFiles],['tables'=>$requiredTables,'files'=>$requiredFiles],['production_enabled'=>false,'secrets_checked'=>false])];}
}
